const ALL_TARGET_BLOCKS: readonly TargetBlock[] = [...TARGET_BLOCKS, ...CORE_TARGET_BLOCKS, ...MACRO_TARGET_BLOCKS, ...MESO_TARGET_BLOCKS, ...MICRO_TARGET_BLOCKS, ...COMPLETION_TRANCHE_SIX_TARGET_BLOCKS, ...RESEARCH_TRANCHE_SEVEN_TARGET_BLOCKS, ...RESEARCH_TRANCHE_EIGHT_TARGET_BLOCKS, ...RESEARCH_TRANCHE_NINE_TARGET_BLOCKS, ...RESEARCH_TRANCHE_TEN_TARGET_BLOCKS, ...RESEARCH_TRANCHE_ELEVEN_TARGET_BLOCKS, ...RESEARCH_TRANCHE_TWELVE_TARGET_BLOCKS, ...RESEARCH_TRANCHE_THIRTEEN_TARGET_BLOCKS, ...RESEARCH_TRANCHE_FOURTEEN_TARGET_BLOCKS, ...RESEARCH_TRANCHE_FIFTEEN_TARGET_BLOCKS];

export const RESEARCH_CANDIDATES: readonly ResearchQuestionCandidate[] = ALL_TARGET_BLOCKS.flatMap((targetBlock) =>
  targetBlock.items.map((seed) => candidateFromSeed(targetBlock, seed)),
);

export const RESEARCH_PRIORITY_TARGET_IDS: readonly string[] = ALL_TARGET_BLOCKS.map((targetBlock) => targetBlock.targetId);

const dimension = (
  facetId: string,
  layer: Layer,
  expectedDirection: ResearchQualitativeDirection,
  centrality: ResearchAnchorCentrality,
  rationale: string,
  sourceIds: readonly string[],
): ResearchAnchorDimension => ({ facetId, layer, expectedDirection, centrality, rationale, sourceIds });

const anchorConception = (
  conceptId: string,
  layer: Exclude<Layer, "descriptive">,
  label: string,
  interpretation: string,
  centrality: ResearchAnchorCentrality,
  sourceIds: readonly string[],
): ResearchAnchorConception => ({ conceptId, layer, label, interpretation, centrality, sourceIds });

const relationParticipant = (kind: ResearchAnchorRelationParticipant["kind"], id: string): ResearchAnchorRelationParticipant => ({ kind, id });

const facetParticipants = (...facetIds: string[]): readonly ResearchAnchorRelationParticipant[] => facetIds.map((facetId) => relationParticipant("facet", facetId));

const researchedRelation = (
  id: string,
  kind: ResearchAnchorRelationKind,
  statement: string,
  participants: readonly ResearchAnchorRelationParticipant[],
  sourceIds: readonly string[],
  evidencePosture: ResearchAnchorRelation["evidencePosture"] = "source-backed-contested",
): ResearchAnchorRelation => ({ id, kind, statement, participants, evidencePosture, sourceIds });

const profile = (
  targetId: string,
  definition: string,
  boundary: string,
  variants: readonly string[],
  neighbors: readonly string[],
  sourceIds: readonly string[],
  dimensions: readonly ResearchAnchorDimension[],
): ResearchAnchorProfile => ({
  targetId,
  targetLabel: targetLabelFor(targetId),
  definition,
  boundary,
  variants,
  neighbors,
  dimensions,
  conceptions: [],
  relationships: [],
  sourceIds,
  status: "research_candidate",
});

